[{"order":1,"type":"heading","text":"Deep Linking and Universal Links Integration in SwiftUI"},{"order":2,"type":"paragraph","text":"Deep linking allows users to navigate directly to specific content within your SwiftUI application using custom URL schemes or Universal Links. Universal Links provide a secure, seamless way to open your app via standard HTTP/HTTPS web links."},{"order":3,"type":"subheading","text":"Step 1: Configuring Associated Domains"},{"order":4,"type":"paragraph","text":"To support Universal Links, you must configure Associated Domains in your Xcode project and host an apple-app-site-association file on your web server."},{"order":5,"type":"bullet_point","text":"Open your Xcode project, select your target, and go to the Signing & Capabilities tab."},{"order":6,"type":"bullet_point","text":"Click + Capability and add Associated Domains."},{"order":7,"type":"bullet_point","text":"Add your domain using the format: applinks:yourdomain.com."},{"order":8,"type":"subheading","text":"Step 2: Handling Incoming URLs in SwiftUI"},{"order":9,"type":"paragraph","text":"In SwiftUI, you handle incoming deep links and Universal Links using the onOpenURL modifier at the root of your application view hierarchy."},{"order":10,"type":"code","text":"import SwiftUI

@main
struct DeepLinkApp: App {
    @StateObject private var deepLinkManager = DeepLinkManager()

    var body: some Scene {
        WindowGroup {
            ContentView()
                .environmentObject(deepLinkManager)
                .onOpenURL { url in
                    deepLinkManager.handle(url: url)
                }
        }
    }
}"},{"order":11,"type":"subheading","text":"Step 3: Creating a Deep Link Router"},{"order":12,"type":"paragraph","text":"A centralized router parses the URL path and query parameters to update your app state and navigate users to the correct view."},{"order":13,"type":"code","text":"class DeepLinkManager: ObservableObject {
    @Published var selectedTab: Int = 0
    @Published var detailItemId: String? = nil

    func handle(url: URL) {
        guard url.scheme == "myapp" || url.host == "yourdomain.com" else { return }

        let pathComponents = url.pathComponents
        if pathComponents.contains("item") {
            if let index = pathComponents.firstIndex(of: "item"), pathComponents.indices.contains(index + 1) {
                self.detailItemId = pathComponents[index + 1]
                self.selectedTab = 1
            }
        }
    }
}"},{"order":14,"type":"subheading","text":"Step 4: Navigating Based on Deep Links"},{"order":15,"type":"paragraph","text":"Finally, consume the state published by your manager in your views using standard SwiftUI navigation mechanisms like NavigationStack."},{"order":16,"type":"code","text":"struct ContentView: View {
    @EnvironmentObject var deepLinkManager: DeepLinkManager

    var body: some View {
        TabView(selection: $deepLinkManager.selectedTab) {
            HomeView()
                .tabItem { Label("Home", systemImage: "house") }
                .tag(0)

            NavigationStack {
                ItemListView()
                    .navigationDestination(isPresented: Binding(
                        get: { deepLinkManager.detailItemId != nil },
                        set: { if !$0 { deepLinkManager.detailItemId = nil } }
                    )) {
                        if let itemId = deepLinkManager.detailItemId {
                            ItemDetailView(itemId: itemId)
                        }
                    }
            }
            .tabItem { Label("Items", systemImage: "list.bullet") }
            .tag(1)
        }
    }
}"}]
